document.addEventListener('DOMContentLoaded', () => {
    const quizForm = document.getElementById('quiz-form');
    const resultsArea = document.getElementById('results');

    const answers = {
        q1: ['c', 'rust', 'cpp'],
        q2: ['js', 'ts', 'css'],
        q3: ['python', 'java']
    };

    quizForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const formData = new FormData(quizForm);
        let score = 0;
        const totalQuestions = Object.keys(answers).length;

        for (const [question, correctAnswers] of Object.entries(answers)) {
            const selectedAnswers = formData.getAll(question);

            // For multi-select, check if exactly the correct ones are selected
            const isCorrect = selectedAnswers.length === correctAnswers.length &&
                              selectedAnswers.every(val => correctAnswers.includes(val));

            if (isCorrect) {
                score++;
            }
        }

        displayResults(score, totalQuestions);
    });

    function displayResults(score, total) {
        resultsArea.innerHTML = `
            <h2>Quiz Results</h2>
            <p>You scored <strong>${score} out of ${total}</strong>!</p>
            <p>${getMessage(score, total)}</p>
        `;
        resultsArea.classList.add('visible');
        resultsArea.scrollIntoView({ behavior: 'smooth' });
    }

    function getMessage(score, total) {
        const percentage = (score / total) * 100;
        if (percentage === 100) return "Perfect! You're a polyglot pro.";
        if (percentage >= 66) return "Great job! You know your languages.";
        if (percentage >= 33) return "Not bad, keep learning!";
        return "Keep studying your programming history!";
    }
});

