11.     quizForm.addEventListener('submit', (e) => {
12.         e.preventDefault();
13. 
14.         const formData = new FormData(quizForm);
15.         let score = 0;
16.         const totalQuestions = Object.keys(answers).length;
17. 
18.         for (const [question, correctAnswers] of Object.entries(answers)) {
19.             const selectedAnswers = formData.getAll(question);
20.             
21.             // For multi-select, check if exactly the correct ones are selected
22.             const isCorrect = selectedAnswers.length === correctAnswers.length &&
23.                               selectedAnswers.every(val => correctAnswers.includes(val));
24.             
25.             if (isCorrect) {
26.                 score++;
27.             }
28.         }
29. 
30.         displayResults(score, totalQuestions);
31.     });
32. 
33.     function displayResults(score, total) {
34.         resultsArea.innerHTML = `
35.             <h2>Quiz Results</h2>
36.             <p>You scored <strong>${score} out of ${total}</strong>!</p>
37.             <p>${getMessage(score, total)}</p>
38.         `;
